import{z as l,x as o,o as B,c as d,q as r,j as n,D as a,d as e,s,S as i,b as A}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"退出机制","description":"","frontmatter":{"title":"退出机制","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/sl-exit-mechanism.md","filePath":"quant/sl-exit-mechanism.md","lastUpdated":1791063341000}'),p={name:"quant/sl-exit-mechanism.md"};function C(D,E,m,c,h,F){const t=o("Mermaid");return B(),d("div",null,[E[2]||(E[2]=r('<h1 id="退出机制" tabindex="-1">退出机制 <a class="header-anchor" href="#退出机制" aria-label="Permalink to &quot;退出机制&quot;">​</a></h1><div class="epigraph"><p>进入的规则写满一页，退出的规则常常一行没有——直到不得不退出的那天，才发现退出本身就是一笔没有模型的交易。</p><footer>—— 据 Federal Reserve SR 11-7 的持续监测原则与本课程前几课口径整理</footer></div><p><a href="/quant/sl-compliance-review">上一课</a>的合规门裁决能不能进、要不要冻结；本课写冻结之后钱怎么出来、策略怎么死、死成什么状态。退出机制就是台账状态机上「实盘/暂停 → 退役」那条边的完整定义：触发、分级、清仓、退役的完成标准。它的核心立场只有一句：退出计划在上线时预写，退出时刻只执行。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>停机不是清仓，这是第一层缺口：<a href="/quant/live-monitoring-handoff">监测状态机</a>停的是信号——不再新开仓，存量持仓怎么办没有任何预案，于是「暂停」无限期化，半仓挂账无人认领，归因从此算不清。第二层缺口是退出自身的市场冲击：拥挤策略退出时往往不止你在退，同一生态位上的对手在同一时刻同向清仓，冲击互相放大——<a href="/quant/sl-capacity-governance">容量课的拥挤预算带</a>反过来读，就是退出时的踩踏预警。第三层缺口是激励：退出时刻的在场者——当期奖金、沉没成本、「再等一个季度」——全部反对退出，临场决定的结果几乎必然偏晚。</p><p><span class="marginnote">直觉类比：拥挤策略一起退出像剧场起火——每个人单独看都走得很理性，加总起来却把出口堵死。容量课的拥挤预算带读数高，等于开场时就知道这个剧场出口窄；退出要拉长窗口、分批走，不是跑得更快，而是别和所有人挤同一个门。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>退出计划作为批准的一部分在上线时入台账，写四样：清仓窗口、参与率上限、对冲腿与衍生品的处置、每级的触发条件。执行分三级。<strong>只停新增</strong>：信号停，存量自然到期或按滚动规则收敛，用于可逆条件——判据临时穿带但死因未明。<strong>计划清仓</strong>：按冲击模型分片、限参与率、用 TCA 复核缺口，用于预算耗尽或计划退役。<strong>立即降险</strong>：合规冻结或硬触发时先对冲后清理，对冲腿本身进限额。退役完成有硬定义：台账状态置退役、现货仓位为零、全部衍生品腿平掉、归因拆分与退出缺口入档——缺一项不算退役，只算「正在退」。</p><p><span class="marginnote">术语翻译：TCA（交易成本分析）是把每笔成交价与「什么都没做时的中间价」相比，量出这笔交易付了多少隐性成本。清仓时用它复核缺口，就是边退边对账——一旦发现实际冲击超出预估，就放慢分片节奏，而不是硬按原计划砸完。</span></p>',9)),(B(),n(i,null,{default:a(()=>[s(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRIG%7B%22%E9%80%80%E5%87%BA%E8%A7%A6%E5%8F%91%22%7D%20--%3E%7C%E5%8F%AF%E9%80%86%E6%9D%A1%E4%BB%B6%7C%20L3%5B%22%E5%8F%AA%E5%81%9C%E6%96%B0%E5%A2%9E%EF%BC%9A%E5%AD%98%E9%87%8F%E5%88%B0%E6%9C%9F%E6%88%96%E6%BB%9A%E5%8A%A8%E6%94%B6%E6%95%9B%22%5D%0A%20%20TRIG%20--%3E%7C%E9%A2%84%E7%AE%97%E8%80%97%E5%B0%BD%E6%88%96%E8%AE%A1%E5%88%92%E9%80%80%E5%BD%B9%7C%20L2%5B%22%E8%AE%A1%E5%88%92%E6%B8%85%E4%BB%93%EF%BC%9A%E5%88%86%E7%89%87%E3%80%81%E5%8F%82%E4%B8%8E%E7%8E%87%E4%B8%8A%E9%99%90%E3%80%81TCA%20%E5%A4%8D%E6%A0%B8%22%5D%0A%20%20TRIG%20--%3E%7C%E5%90%88%E8%A7%84%E5%86%BB%E7%BB%93%E6%88%96%E7%A1%AC%E8%A7%A6%E5%8F%91%7C%20L1%5B%22%E7%AB%8B%E5%8D%B3%E9%99%8D%E9%99%A9%EF%BC%9A%E5%85%88%E5%AF%B9%E5%86%B2%E5%90%8E%E6%B8%85%E7%90%86%22%5D%0A%20%20L3%20--%3E%20RESUME%5B%22%E6%9D%A1%E4%BB%B6%E6%81%A2%E5%A4%8D%EF%BC%9A%E5%9B%9E%E6%BB%9A%E5%8F%A3%E5%BE%84%EF%BC%8C%E4%B8%8D%E9%9C%80%E6%96%B0%E7%89%88%E6%9C%AC%22%5D%0A%20%20L2%20--%3E%20DONE%5B%22%E9%80%80%E5%BD%B9%EF%BC%9A%E4%BB%93%E4%BD%8D%E4%B8%8E%E5%85%A8%E9%83%A8%E5%AF%B9%E5%86%B2%E8%85%BF%E5%BD%92%E9%9B%B6%EF%BC%8C%E5%8F%B0%E8%B4%A6%E7%BD%AE%E9%80%80%E5%BD%B9%22%5D%0A%20%20L1%20--%3E%20DONE%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[e("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,"退出要预写而临时不议，机制在于把退出从「当下的裁决」变成「既定判据的执行」。临场时激励清一色偏向持有，预写计划让推迟退出变成一个需要明说、留痕、有人负责的动作——不作为从此有成本。分级的存在是因为退出的可逆性不同：只停新增可逆，回滚口径即可恢复；计划清仓半可逆，重进场有门槛与冲击；立即降险不可逆，所以批准层级也不同——前两级监测预授权，第三级与合规冻结联动执行。拥挤退出还带外部性：同策略生态位上的同时清仓会放大冲击，因此清仓窗口要参考拥挤相关读数，宁可拉长窗口分批走，不抢同一天。",-1)),(B(),n(i,null,{default:a(()=>[s(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%5B%22%E8%A1%B0%E5%87%8F%E8%A7%A6%E5%8F%91%EF%BC%9A%E5%90%8C%E7%AD%96%E7%95%A5%E5%A4%9A%E5%AE%B6%E5%81%9C%E6%9C%BA%22%5D%20--%3E%20SAME%5B%22%E5%90%8C%E4%B8%80%E7%94%9F%E6%80%81%E4%BD%8D%E5%90%8C%E6%97%B6%E6%B8%85%E4%BB%93%22%5D%0A%20%20SAME%20--%3E%20AMP%5B%22%E5%86%B2%E5%87%BB%E4%BA%92%E7%9B%B8%E6%94%BE%E5%A4%A7%EF%BC%9A%E4%BB%B7%E6%A0%BC%E5%8E%8B%E8%BF%87%E5%86%B2%E5%87%BB%E6%A8%A1%E5%9E%8B%E9%A2%84%E4%BC%B0%22%5D%0A%20%20AMP%20--%3E%20SLIP%5B%22%E9%80%80%E5%87%BA%E7%BC%BA%E5%8F%A3%E8%B6%85%E9%A2%84%E7%AE%97%22%5D%0A%20%20READ%5B%22%E6%8B%A5%E6%8C%A4%E7%9B%B8%E5%85%B3%E8%AF%BB%E6%95%B0%22%5D%20--%3E%20WIN%5B%22%E6%8B%89%E9%95%BF%E6%B8%85%E4%BB%93%E7%AA%97%E5%8F%A3%22%5D%0A%20%20WIN%20--%3E%20SPLIT%5B%22%E5%88%86%E6%89%B9%E9%94%99%E5%B3%B0%E8%B5%B0%EF%BC%9A%E4%B8%8D%E6%8A%A2%E5%90%8C%E4%B8%80%E5%A4%A9%22%5D%0A%20%20SPLIT%20--%3E%20CTRL%5B%22%E7%BC%BA%E5%8F%A3%E5%9B%9E%E5%88%B0%E9%A2%84%E7%AE%97%E5%86%85%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">退役最常见的残留是被遗忘的对冲腿：到期日在两年后的深度虚值期权、名义未平的远期。退出完成的定义必须包含全部衍生品腿，否则资本占用与归因永远算不清。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>退出不是免费期权：频繁停启本身有成本——重进场的冲击与门槛、税、以及团队对判据的钝化，所以「停」与「退」的判据故意不同，停可逆、退不可逆。清仓执行的分片算法与 TCA 细节是交易执行深钻的对象，本课只定窗口与参与率这两个治理参数。退出缺口要进策略全周期账：上线前预估的进出场往返成本本来就是容量与预期收益的一部分，<a href="/quant/strategy-capacity-decay">容量课</a>的净收益曲线若没算退出腿，过零点本身就偏乐观。退役后的卷宗怎么沉淀成组织记忆，是下一课知识管理。</p><p><span class="marginnote">常见误区：初学者容易把「停」当成免费动作——先停了再说，想清楚再回来。实际上重进场有冲击成本与门槛，税和团队对判据的钝化也都在记账。所以停与退的判据故意不同：停可逆、退不可逆，频繁停启本身就是一笔没进模型的交易。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>退出计划上线时入台账：窗口、参与率、对冲腿处置、各级触发条件。</li><li>三级退出按可逆性分：只停新增可逆、计划清仓半可逆、立即降险不可逆，批准层级随之不同。</li><li>退役完成有硬定义：状态置退役、仓位与全部衍生品腿归零、归因与缺口入档。</li><li>拥挤退出有外部性：参考拥挤相关拉长窗口，不与同生态位对手抢同一天。</li><li>出处：停机与预授权口径见<a href="/quant/live-monitoring-handoff">实盘监控与研究再触发</a>；持续监测与退役原则据 Federal Reserve SR 11-7（2011）整理；往返成本与容量见<a href="/quant/strategy-capacity-decay">策略容量与衰减</a>。</li></ul>',6))])}const T=l(p,[["render",C]]);export{f as __pageData,T as default};
